module typo_checker (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] word_count,\n    input wire [511:0] words,\n    input wire [31:0] word_lengths,\n    output reg pair_valid,\n    output reg [3:0] word1_idx,\n    output reg [3:0] word2_idx,\n    output reg done\n);\n\n// State declarations\nlocalparam [3:0] S_IDLE         = 4'd0;\nlocalparam [3:0] S_LOAD         = 4'd1;\nlocalparam [3:0] S_LOOP_I       = 4'd2;\nlocalparam [3:0] S_LOOP_J       = 4'd3;\nlocalparam [3:0] S_CHECK        = 4'd4;\nlocalparam [3:0] S_OUTPUT       = 4'd5;\nlocalparam [3:0] S_INCREMENT_J  = 4'd6;\nlocalparam [3:0] S_INCREMENT_I  = 4'd7;\nlocalparam [3:0] S_DONE         = 4'd8;\n\nreg [3:0] state;\nreg [2:0] i, j;\nreg [2:0] i_reg, j_reg;\n\n// Word storage\nreg [63:0] words_reg [0:7];\nreg [3:0] word_lengths_reg [0:7];\n\n// Similarity check\nwire is_similar;\n\nsimilar sim_inst (\n    .word1(words_reg[i]),\n    .len1(word_lengths_reg[i]),\n    .word2(words_reg[j]),\n    .len2(word_lengths_reg[j]),\n    .is_similar(is_similar)\n);\n\n// State Machine\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= S_IDLE;\n        pair_valid <= 1'b0;\n        done <= 1'b0;\n        i <= 3'd0;\n        j <= 3'd0;\n        for (integer w = 0; w < 8; w = w + 1) begin\n            words_reg[w] <= 64'd0;\n            word_lengths_reg[w] <= 4'd0;\n        end\n    end else begin\n        case (state)\n            S_IDLE: begin\n                done <= 1'b0;\n                pair_valid <= 1'b0;\n                if (start) begin\n                    state <= S_LOAD;\n                end\n            end\n            \n            S_LOAD: begin\n                for (integer w = 0; w < 8; w = w + 1) begin\n                    words_reg[w] <= words[w*64 +: 64];\n                    word_lengths_reg[w] <= word_lengths[w*4 +: 4];\n                end\n                i <= 3'd0;\n                j <= 3'd0;\n                state <= S_LOOP_I;\n            end\n            \n            S_LOOP_I: begin\n                if (word_count <= 4'd1) begin\n                    state <= S_DONE;\n                end else if (i < (word_count - 1)) begin\n                    j <= i + 1;\n                    state <= S_LOOP_J;\n                end else begin\n                    state <= S_DONE;\n                end\n            end\n            \n            S_LOOP_J: begin\n                if (j < word_count) begin\n                    state <= S_CHECK;\n                end else begin\n                    state <= S_INCREMENT_I;\n                end\n            end\n            \n            S_CHECK: begin\n                if (is_similar) begin\n                    i_reg <= i;\n                    j_reg <= j;\n                    state <= S_OUTPUT;\n                end else begin\n                    state <= S_INCREMENT_J;\n                end\n            end\n            \n            S_OUTPUT: begin\n                pair_valid <= 1'b1;\n                word1_idx <= {1'b0, i_reg};\n                word2_idx <= {1'b0, j_reg};\n                state <= S_INCREMENT_J;\n            end\n            \n            S_INCREMENT_J: begin\n                pair_valid <= 1'b0;\n                j <= j + 1;\n                state <= S_LOOP_J;\n            end\n            \n            S_INCREMENT_I: begin\n                i <= i + 1;\n                state <= S_LOOP_I;\n            end\n            \n            S_DONE: begin\n                done <= 1'b1;\n                state <= S_IDLE;\n            end\n            \n            default: state <= S_IDLE;\n        endcase\n    end\nend\n\nendmodule\n\nmodule similar (\n    input [63:0] word1,\n    input [3:0] len1,\n    input [63:0] word2,\n    input [3:0] len2,\n    output reg is_similar\n);\n\nalways @(*) begin\n    is_similar = 1'b0;\n    \n    // Delete check\n    if (len1 == (len2 + 1)) begin\n        for (integer skip = 0; skip < len1; skip = skip + 1) begin\n            bit match = 1'b1;\n            for (integer k = 0; k < skip; k = k + 1) begin\n                if (word1[k*8 +:8] != word2[k*8 +:8]) match = 1'b0;\n            end\n            for (integer k = skip; k < len2; k = k + 1) begin\n                if (word1[(k+1)*8 +:8] != word2[k*8 +:8]) match = 1'b0;\n            end\n            if (match) is_similar = 1'b1;\n        end\n    end\n    \n    // Insert check\n    else if (len2 == (len1 + 1)) begin\n        for (integer skip = 0; skip < len2; skip = skip + 1) begin\n            bit match = 1'b1;\n            for (integer k = 0; k < skip; k = k + 1) begin\n                if (word2[k*8 +:8] != word1[k*8 +:8]) match = 1'b0;\n            end\n            for (integer k = skip; k < len1; k = k + 1) begin\n                if (word2[(k+1)*8 +:8] != word1[k*8 +:8]) match = 1'b0;\n            end\n            if (match) is_similar = 1'b1;\n        end\n    end\n    \n    // Replace/transpose check\n    else if (len1 == len2) begin\n        // Replace\n        integer diff_count = 0;\n        for (integer k = 0; k < len1; k = k + 1) begin\n            if (word1[k*8 +:8] != word2[k*8 +:8]) diff_count = diff_count + 1;\n        end\n        if (diff_count == 1) is_similar = 1'b1;\n        \n        // Transpose\n        for (integer pos = 0; pos < len1 - 1; pos = pos + 1) begin\n            if (\n                (word1[pos*8 +:8] == word2[(pos+1)*8 +:8]) &&\n                (word1[(pos+1)*8 +:8] == word2[pos*8 +:8])\n            ) begin\n                bit others_match = 1'b1;\n                for (integer k = 0; k < len1; k = k + 1) begin\n                    if (k != pos && k != (pos+1)) begin\n                        if (word1[k*8 +:8] != word2[k*8 +:8]) others_match = 1'b0;\n                    end\n                end\n                if (others_match) is_similar = 1'b1;\n            end\n        end\n    end\nend\n\nendmodule